import React, { useState, useMemo, useEffect } from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";
import * as LucideIcons from "https://esm.sh/lucide-react@0.292.0";

const utilityIcons = {
  BIOMASS: "Leaf",
  CABLE: "Tv",
  CARBONDIOXIDE: "Wind",
  CHILLEDWATER: "Snowflake",
  DIESEL: "Fuel",
  ELECTRIC: "Zap",
  FIREPROTECTION: "Shield",
  FUELCELL: "BatteryCharging",
  HOTWATER: "Flame",
  INTERNET: "Wifi",
  IRRIGATION: "Sprout",
  LIGHTING: "Lightbulb",
  NATURALGAS: "Flame",
  NG_COGEN: "Factory",
  NITROGEN: "FlaskConical",
  OIL2: "Fuel",
  OIL4: "Fuel",
  OIL6: "Fuel",
  OTHER: "Package",
  OXYGEN: "Activity",
  PESTCONTROL: "Bug",
  PROPANE: "Flame",
  REFUSE: "Trash2",
  SEWER: "Waves",
  SOLARPV: "Sun",
  STEAM: "CloudFog",
  STORMDRAIN: "CloudRain",
  STORMWATER: "CloudRainWind",
  TELEPHONE: "UtilityPole",
  UNLEADEDFUEL: "Fuel",
  UTILITYGAS: "Flame",
  WATER: "Droplet"
};

const capitalize = (s) => s ? s.charAt(0).toUpperCase() + s.slice(1).toLowerCase() : "";
const PAGE_SIZE = 20;

function App() {
  const [model, setModel] = useState(appsmith.model || {});
  const [sortDir, setSortDir] = useState("asc");
  const [page, setPage] = useState(1);
  const [gotoVal, setGotoVal] = useState("");

  useEffect(() => {
    const id = setInterval(() => setModel({ ...(appsmith.model || {}) }), 400);
    return () => clearInterval(id);
  }, []);

  const rows = useMemo(() => {
    const data = (model && model.data) || [];
    const list = data.map((r) => (r && (r.utility || r.commodity)) || "").filter(Boolean);
    list.sort((a, b) => sortDir === "asc" ? a.localeCompare(b) : b.localeCompare(a));
    return list;
  }, [model, sortDir]);

  const totalPages = Math.max(1, Math.ceil(rows.length / PAGE_SIZE));
  const safePage = Math.min(page, totalPages);
  const start = (safePage - 1) * PAGE_SIZE;
  const pageRows = rows.slice(start, start + PAGE_SIZE);

  const toggleSort = () => setSortDir(sortDir === "asc" ? "desc" : "asc");

  const goToPage = (p) => {
    if (!Number.isFinite(p)) return;
    const clamped = Math.max(1, Math.min(totalPages, Math.floor(p)));
    setPage(clamped);
  };

  const onGotoSubmit = (e) => {
    if (e.key === "Enter") {
      const n = parseInt(gotoVal, 10);
      if (!isNaN(n)) goToPage(n);
      setGotoVal("");
    }
  };

  if (model.isLoading) {
    return React.createElement("div", { className: "skel" }, "Loading utilities...");
  }

  return React.createElement("div", { className: "wrap" },
    React.createElement("table", { className: "tbl" },
      React.createElement("thead", null,
        React.createElement("tr", null,
          React.createElement("th", { onClick: toggleSort },
            "Utility Type",
            React.createElement("span", { className: "sort" },
              React.createElement("span", { className: sortDir === "asc" ? "active" : "" }, "\u25B2"),
              React.createElement("span", { className: sortDir === "desc" ? "active" : "" }, "\u25BC")
            )
          )
        )
      ),
      React.createElement("tbody", null,
        pageRows.length === 0
          ? React.createElement("tr", null, React.createElement("td", { className: "empty" }, "No utilities found"))
          : pageRows.map((u, i) => {
              const key = (u || "").toUpperCase();
              const iconName = utilityIcons[key] || "Package";
              const Icon = LucideIcons[iconName] || LucideIcons.Package;
              return React.createElement("tr", { key: i },
                React.createElement("td", null,
                  React.createElement("span", { className: "cell" },
                    React.createElement(Icon, { size: 18, strokeWidth: 1.8 }),
                    React.createElement("span", { className: "label" }, capitalize(u))
                  )
                )
              );
            })
      )
    ),
    React.createElement("div", { className: "pager" },
      React.createElement("button", { className: "pbtn", disabled: safePage <= 1, onClick: () => goToPage(safePage - 1) }, "\u2039"),
      React.createElement("span", { className: "pnum" }, safePage),
      React.createElement("button", { className: "pbtn", disabled: safePage >= totalPages, onClick: () => goToPage(safePage + 1) }, "\u203A"),
      React.createElement("span", { className: "gotolbl" }, "Go to"),
      React.createElement("input", {
        className: "goto",
        type: "number",
        min: 1,
        max: totalPages,
        value: gotoVal,
        onChange: (e) => setGotoVal(e.target.value),
        onKeyDown: onGotoSubmit,
        placeholder: String(safePage)
      })
    )
  );
}

ReactDOM.render(React.createElement(App, null), document.getElementById("root"));

